import type {
  Align,
  Fill,
  Interaction,
  Motion,
  SceneDocument,
  SceneNode,
  Weight,
} from './schema';
import { isContainer } from './schema';

// Codegen is a compiler, not a prompt.
//
// This is the part that has to be boring. If the code panel were generated by a
// model it could drift from what the canvas shows, and the guarantee this whole
// product rests on — that what a designer tuned is literally what ships — would
// be a hope rather than a property of the system. So: a pure function over the
// same tree the canvas renders, no I/O, no cleverness.

const IND = '    ';

interface Ctx {
  lines: string[];
  /** Sheet state vars hoisted to the top of the view, in declaration order. */
  states: Map<string, string>;
}

function push(ctx: Ctx, depth: number, line: string) {
  ctx.lines.push(line ? IND.repeat(depth) + line : '');
}

// ---------------------------------------------------------------- values

function swiftAlign(align: Align): string {
  return align === 'leading' ? '.leading' : align === 'center' ? '.center' : '.trailing';
}

function frameAlign(align: Align): string {
  return align === 'leading'
    ? '.topLeading'
    : align === 'center'
      ? '.top'
      : '.topTrailing';
}

function swiftWeight(weight: Weight): string {
  return `.${weight}`;
}

function colorLiteral(hex: string): string {
  return `Color(hex: "${hex}")`;
}

/**
 * CSS-style angle (0° points up, increasing clockwise) to the two UnitPoints
 * SwiftUI wants. Done arithmetically rather than by snapping to `.topLeading`
 * and friends so an arbitrary dial angle survives the trip to code.
 */
function gradientPoints(angle: number): { start: string; end: string } {
  const rad = (angle * Math.PI) / 180;
  const dx = Math.sin(rad) / 2;
  const dy = -Math.cos(rad) / 2;
  const r = (n: number) => Number(n.toFixed(3));
  return {
    start: `UnitPoint(x: ${r(0.5 - dx)}, y: ${r(0.5 - dy)})`,
    end: `UnitPoint(x: ${r(0.5 + dx)}, y: ${r(0.5 + dy)})`,
  };
}

function fillExpression(fill: Fill): string {
  if (fill.type === 'solid') return colorLiteral(fill.color);
  const stops = [...fill.stops]
    .sort((a, b) => a.pos - b.pos)
    .map(
      (s) =>
        `.init(color: ${colorLiteral(s.color)}, location: ${(s.pos / 100).toFixed(2)})`,
    )
    .join(', ');
  const { start, end } = gradientPoints(fill.angle);
  return `LinearGradient(stops: [${stops}], startPoint: ${start}, endPoint: ${end})`;
}

function motionExpression(motion: Motion): string {
  if (motion.type === 'spring') {
    // interpolatingSpring takes the same two numbers the inspector edits, so the
    // preview and the shipped animation are driven by identical parameters.
    return `.interpolatingSpring(stiffness: ${motion.stiffness}, damping: ${motion.damping})`;
  }
  const easing =
    motion.easing === 'linear'
      ? '.linear'
      : motion.easing === 'easeIn'
        ? '.easeIn'
        : motion.easing === 'easeOut'
          ? '.easeOut'
          : '.easeInOut';
  return `${easing}(duration: ${(motion.duration / 1000).toFixed(2)})`;
}

function stateName(label: string): string {
  const words = label.replace(/[^a-zA-Z0-9 ]/g, '').split(/\s+/).filter(Boolean);
  const camel = words
    .map((w, i) =>
      i === 0
        ? w.toLowerCase()
        : w.charAt(0).toUpperCase() + w.slice(1).toLowerCase(),
    )
    .join('');
  return `show${camel.charAt(0).toUpperCase()}${camel.slice(1)}`;
}

function viewName(docName: string): string {
  const words = docName.replace(/[^a-zA-Z0-9 ]/g, '').split(/\s+/).filter(Boolean);
  const pascal = words
    .map((w) => w.charAt(0).toUpperCase() + w.slice(1))
    .join('');
  return `${pascal || 'Generated'}View`;
}

// ---------------------------------------------------------------- emit

function emitInteraction(ctx: Ctx, depth: number, interaction: Interaction) {
  const label = interaction.actionLabel ?? 'Detail';
  const name = stateName(label);
  if (interaction.action === 'openSheet') {
    ctx.states.set(name, 'false');
    push(ctx, depth, `.sheet(isPresented: $${name}) {`);
    push(ctx, depth + 1, `${viewName(label)}()`);
    push(ctx, depth + 2, `.presentationDetents([.medium])`);
    push(ctx, depth, `}`);
    push(
      ctx,
      depth,
      `.animation(${motionExpression(interaction.motion)}, value: ${name})`,
    );
  }
}

function emitNode(ctx: Ctx, node: SceneNode, depth: number) {
  switch (node.type) {
    case 'screen':
    case 'stack': {
      const p = node.props;
      const container = node.type === 'screen';
      const stack = p.direction === 'vertical' ? 'VStack' : 'HStack';
      const alignArg =
        p.direction === 'vertical'
          ? `alignment: ${swiftAlign(p.align)}, `
          : '';
      push(ctx, depth, `${stack}(${alignArg}spacing: ${p.gap}) {`);
      if (isContainer(node) && node.children) {
        node.children.forEach((child, i) => {
          if (i > 0) push(ctx, depth + 1, '');
          emitNode(ctx, child, depth + 1);
        });
      }
      push(ctx, depth, `}`);
      if (p.padding > 0) push(ctx, depth + 1, `.padding(${p.padding})`);
      if (container) {
        push(
          ctx,
          depth + 1,
          `.frame(maxWidth: .infinity, maxHeight: .infinity, alignment: ${frameAlign(p.align)})`,
        );
        push(
          ctx,
          depth + 1,
          `.background(${colorLiteral((node.props as { background: string }).background)}.ignoresSafeArea())`,
        );
      } else if ('opacity' in p && p.opacity < 100) {
        push(ctx, depth + 1, `.opacity(${(p.opacity / 100).toFixed(2)})`);
      }
      break;
    }

    case 'text': {
      const p = node.props;
      push(ctx, depth, `Text("${p.content.replace(/"/g, '\\"')}")`);
      push(
        ctx,
        depth + 1,
        `.font(.system(size: ${p.size}, weight: ${swiftWeight(p.weight)}))`,
      );
      push(ctx, depth + 1, `.foregroundStyle(${colorLiteral(p.color)})`);
      if (p.opacity < 100) push(ctx, depth + 1, `.opacity(${(p.opacity / 100).toFixed(2)})`);
      break;
    }

    case 'box': {
      const p = node.props;
      push(ctx, depth, `RoundedRectangle(cornerRadius: ${p.cornerRadius})`);
      push(ctx, depth + 1, `.fill(${fillExpression(p.fill)})`);
      push(ctx, depth + 1, `.frame(maxWidth: .infinity, minHeight: ${p.height})`);
      if (p.shadow) {
        push(ctx, depth + 1, `.shadow(color: .black.opacity(0.35), radius: 18, y: 10)`);
      }
      if (p.opacity < 100) push(ctx, depth + 1, `.opacity(${(p.opacity / 100).toFixed(2)})`);
      break;
    }

    case 'button': {
      const p = node.props;
      const action = node.interaction
        ? `${stateName(node.interaction.actionLabel ?? 'Detail')} = true`
        : '';
      push(ctx, depth, `Button {`);
      push(ctx, depth + 1, action || `// no action bound`);
      push(ctx, depth, `} label: {`);
      push(ctx, depth + 1, `Text("${p.label.replace(/"/g, '\\"')}")`);
      push(ctx, depth + 2, `.font(.system(size: 15, weight: .semibold))`);
      push(ctx, depth + 2, `.foregroundStyle(${colorLiteral(p.textColor)})`);
      push(
        ctx,
        depth + 2,
        `.frame(maxWidth: .infinity, minHeight: ${p.height})`,
      );
      push(ctx, depth, `}`);
      push(ctx, depth + 1, `.background(${fillExpression(p.fill)})`);
      push(
        ctx,
        depth + 1,
        `.clipShape(RoundedRectangle(cornerRadius: ${p.cornerRadius}))`,
      );
      if (p.opacity < 100) push(ctx, depth + 1, `.opacity(${(p.opacity / 100).toFixed(2)})`);
      if (node.interaction) emitInteraction(ctx, depth + 1, node.interaction);
      break;
    }
  }
}

const COLOR_HELPER = `
// Generated helper — hex initialiser SwiftUI doesn't ship with.
extension Color {
    init(hex: String) {
        let raw = hex.hasPrefix("#") ? String(hex.dropFirst()) : hex
        var value: UInt64 = 0
        Scanner(string: raw).scanHexInt64(&value)
        self.init(
            .sRGB,
            red: Double((value >> 16) & 0xFF) / 255,
            green: Double((value >> 8) & 0xFF) / 255,
            blue: Double(value & 0xFF) / 255,
            opacity: 1
        )
    }
}`.trim();

export function generateSwift(doc: SceneDocument): string {
  const bodyCtx: Ctx = { lines: [], states: new Map() };
  emitNode(bodyCtx, doc.root, 2);

  const name = viewName(doc.name);
  const header = ['import SwiftUI', '', `struct ${name}: View {`];

  const stateLines = [...bodyCtx.states.entries()].map(
    ([key, init]) => `${IND}@State private var ${key} = ${init}`,
  );

  const out = [
    ...header,
    ...stateLines,
    ...(stateLines.length ? [''] : []),
    `${IND}var body: some View {`,
    ...bodyCtx.lines,
    `${IND}}`,
    `}`,
    '',
    COLOR_HELPER,
  ];

  return out.join('\n');
}

/** Minimal Swift tokeniser for the code panel. Structure only — enough to make
 *  the output scannable, not a full grammar. */
export type Token = { text: string; cls: string };

const KEYWORDS = new Set([
  'import',
  'struct',
  'var',
  'let',
  'some',
  'private',
  'extension',
  'init',
  'self',
  'true',
  'false',
  'if',
  'return',
]);

export function tokenizeSwift(line: string): Token[] {
  const tokens: Token[] = [];
  const re = /(\/\/.*$)|("(?:[^"\\]|\\.)*")|(\b\d+(?:\.\d+)?\b)|(\b[A-Za-z_][A-Za-z0-9_]*\b)|(\s+)|(.)/g;
  let m: RegExpExecArray | null;
  while ((m = re.exec(line))) {
    const [text, comment, str, num, word, space] = m;
    if (comment) tokens.push({ text, cls: 'tk-comment' });
    else if (str) tokens.push({ text, cls: 'tk-string' });
    else if (num) tokens.push({ text, cls: 'tk-number' });
    else if (word) {
      if (KEYWORDS.has(text)) tokens.push({ text, cls: 'tk-keyword' });
      else if (/^[A-Z]/.test(text)) tokens.push({ text, cls: 'tk-type' });
      else tokens.push({ text, cls: 'tk-plain' });
    } else if (space) tokens.push({ text, cls: 'tk-plain' });
    else tokens.push({ text, cls: 'tk-punct' });
  }
  return tokens;
}
